    chingis: {b:"chingisid", a:["Чингис", "Чингис-хан", "Темучин"], q:1, bio:"В 1206 году Темучин объединил степные племена и был провозглашён Чингисханом. Его держава начала походы в Китай и Среднюю Азию. В 1223 году его полководцы разгромили русско-половецкое войско на Калке."},
